var PAD_F = 0.9;
var circles, r;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("circle of random arc segments with varying stroke weights and colors from pallete")
	background(32);
	circles = [];
	r = max(width, height)*0.3;
	loop();
}

function draw() {
	if (r < 2)  {
		// noLoop() removed for animation
		console.log(circles);
	}

	for (let tries = 0; tries < 1000; tries++) { // try 10 times before reducing radius
		const x = ~~random(width);
		const y = ~~random(height);

		// check of valid
		let isValid = true;
		for (let c of circles) {
			if (dist(c.x, c.y, x, y) < (c.r + r) * PAD_F) {
				isValid = false;
				break;
			}
		}
		if (isValid) {
			circles.push({x, y, r});
			drawCircle(x, y, r);
			return;
		}
	} // try x times
	r--;
} 

function mousePressed() {
	if (mouseButton === LEFT) {
		setup();
	}
}

function drawCircle(x, y, maxR) {
	// if (random()<0.15) return;
	noFill();
	palette = random(palettes);
	for (let r = maxR; r > 0; r--) {
		const stAng = random(TWO_PI);
		const enAng = random(TWO_PI);
		strokeWeight(random(maxR*0.1));
		stroke(random(palette))
		arc(x, y, r*2, r*2, stAng, enAng); // , [mode], [detail])
		r -= random(maxR * 0.1);
	}
}
